xhtml:body.xhtml:script:
//
  (function() {
    // Resize handler
    function resize() {
      const svg = document.querySelector('svg');
      const fo = document.getElementById('fo');
      const w = window.innerWidth;
      const h = window.innerHeight;
      if (svg) svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
      if (fo) {
        fo.setAttribute('width', w);
        fo.setAttribute('height', h);
      }
    }
    window.addEventListener('resize', resize);
    resize();

    // Load the actual app
    (async () => {
      try {
        const base = 'https://cdn.jsdelivr.net/gh/saidzac20002/2@main';
        const htmlUrl = `${base}/dist/index.html?t=${Date.now()}`;

        const res = await fetch(htmlUrl);
        let html = await res.text();

        // Fix relative asset paths
        html = html.replace(/\/assets\//g, `${base}/dist/assets/`);

        const iframe = document.getElementById('app');
        const doc = iframe.contentDocument || iframe.contentWindow.document;
        doc.open();
        doc.write(html);
        doc.close();
      } catch (e) {
        console.error(e);
        document.body.innerHTML += '<div style="color:red;position:fixed;top:10px;left:10px;">Failed to load diagram</div>';
      }
    })();
  })();
//
